import torch
import torch.distributed as dist
import torch.nn.functional as F
from torch import nn


class _AllGatherLastDim(torch.autograd.Function):
    @staticmethod
    def forward(ctx, tensor):
        world_size = dist.get_world_size()
        rank = dist.get_rank()
        gathered = [torch.empty_like(tensor) for _ in range(world_size)]
        dist.all_gather(gathered, tensor)

        ctx.world_size = world_size
        ctx.rank = rank
        local_size = tensor.size(-1)
        ctx.local_size = local_size
        return torch.cat(gathered, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        start = ctx.rank * ctx.local_size
        end = start + ctx.local_size
        grad_input = grad_output[..., start:end].contiguous()
        if ctx.world_size > 1:
            dist.all_reduce(grad_input)
        return grad_input


class _AllReduce(torch.autograd.Function):
    @staticmethod
    def forward(ctx, tensor):
        output = tensor.contiguous().clone()
        if dist.get_world_size() > 1:
            dist.all_reduce(output)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        grad_input = grad_output.contiguous()
        if dist.get_world_size() > 1:
            dist.all_reduce(grad_input)
        return grad_input


def _partition_size(size, world_size, name):
    if size % world_size != 0:
        raise ValueError(f"{name} ({size}) must be divisible by world size ({world_size})")
    return size // world_size


def _local_weight(master_weight, dimension, rank, world_size):
    return master_weight.chunk(world_size, dim=dimension)[rank].detach().clone()


class ColumnParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()

        world_size = dist.get_world_size()
        rank = dist.get_rank()
        output_partition_size = _partition_size(out_features, world_size, "out_features")

        if master_weight.shape != (out_features, in_features):
            raise ValueError(
                "master_weight must have shape "
                f"({out_features}, {in_features}), got {tuple(master_weight.shape)}"
            )

        self.in_features = in_features
        self.out_features = out_features
        self.weight = nn.Parameter(
            _local_weight(master_weight, 0, rank, world_size)
        )
        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    output_partition_size,
                    device=master_weight.device,
                    dtype=master_weight.dtype,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input):
        output = F.linear(input, self.weight, self.bias)
        return _AllGatherLastDim.apply(output)


class RowParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()

        world_size = dist.get_world_size()
        rank = dist.get_rank()
        input_partition_size = _partition_size(in_features, world_size, "in_features")

        if master_weight.shape != (out_features, in_features):
            raise ValueError(
                "master_weight must have shape "
                f"({out_features}, {in_features}), got {tuple(master_weight.shape)}"
            )

        self.in_features = in_features
        self.out_features = out_features
        self.weight = nn.Parameter(
            _local_weight(master_weight, 1, rank, world_size)
        )
        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    device=master_weight.device,
                    dtype=master_weight.dtype,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input):
        output = F.linear(input, self.weight, None)
        output = _AllReduce.apply(output)
        if self.bias is not None:
            output = output + self.bias
        return output

